def findMaximumNum(s, K):
    def backtrack(s, K, max_num):
        if K == 0:
            return s
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n):
                if s[i] < s[j]:
                    swapped = s[:i] + s[j] + s[i + 1:j] + s[i] + s[j + 1:]
                    if swapped > max_num[0]:
                        max_num[0] = swapped
                    max_num[0] = backtrack(swapped, K - 1, max_num)
        return max_num[0]
    max_num = [s]
    return backtrack(s, K, max_num)
